package com.fitconnect.booking.service; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; @Component public class BookingScheduler {private final BookingService service;public BookingScheduler(BookingService service){this.service=service;}@Scheduled(fixedDelayString="${fitconnect.scheduler.expiration-delay:300000}") public void expire(){service.expire();}@Scheduled(fixedDelayString="${fitconnect.scheduler.reminder-delay:300000}") public void remind(){service.remind();}}
